{
  "description": "The creature is a single four-legged mammal shown in right-facing profile standing on sparse grass and dirt. Its overall body shape, fur, head and tail are goat-like, with long shaggy brown fur that is lighter on the belly and neck and darker on the legs and face, while its back, sides of the hindquarters, shoulders and underside are covered by a hard, domed reptile shell. The shell on the back is large and covers from the base of the neck to the rump, and smaller patches of the same shelled material cover the upper front and hind legs, with a pale plastron visible along the lower belly between the legs.",
  "parts": [
    {
      "part": "head",
      "looks_like": "goat-like head with an elongated muzzle, dark nostrils, a closed mouth, a brown eye with a horizontal pupil, and long hair on the chin forming a beard",
      "where": "at the front end of the body on top of the neck, facing to the right"
    },
    {
      "part": "horns",
      "looks_like": "two thick, dark brown to black, backward-curving horns with transverse ridges and pointed tips",
      "where": "on top of the head behind the forehead, one on each side"
    },
    {
      "part": "ears",
      "looks_like": "two medium-sized, pointed, fur-covered ears with visible inner ear detail",
      "where": "on the sides of the head just behind and below the horns"
    },
    {
      "part": "mane",
      "looks_like": "long, shaggy, light to medium brown fur that is thicker and longer than the body fur",
      "where": "along the dorsal and ventral sides of the neck and extending onto the chest and brisket"
    },
    {
      "part": "legs",
      "looks_like": "four sturdy, straight, fur-covered legs with visible joints; the upper portions of all four legs are overlaid by hard shelled plates, the lower portions are fully furred",
      "where": "two forelegs under the chest/shoulder and two hind legs under the rump, supporting the body"
    },
    {
      "part": "feet",
      "looks_like": "four cloven hooves, dark brown/black, with short fur extending down to the hoof edge",
      "where": "at the distal end of each leg in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "short, fluffy, light brown hairy tail with wispy fur",
      "where": "at the posterior end of the body, protruding from beneath the rear edge of the dorsal shell"
    },
    {
      "part": "shell",
      "looks_like": "large, high-domed carapace composed of polygonal scutes with raised pyramidal centers and concentric growth rings, colored in mottled brown, tan and dark brown/black with dark borders between scutes",
      "where": "covering the entire dorsal back from just behind the shoulders to just in front of the tail, sitting on top of the fur"
    },
    {
      "part": "plates",
      "looks_like": "smaller clusters of the same hard, scuted material as the dorsal shell, forming segmented armor patches with polygonal scutes and banded segments extending down the leg",
      "where": "on the outer side of each hind thigh/hip and on the shoulder/upper foreleg, with narrow bands continuing down the front and hind legs"
    },
    {
      "part": "scales",
      "looks_like": "hard keratinous scutes with ridged, layered texture and dark edging, forming the shell and leg plates",
      "where": "forming the surface of the dorsal shell and the leg plates"
    },
    {
      "part": "markings",
      "looks_like": "mottled brown fur with lighter cream on the belly and inner legs, darker brown on the lower legs and face, and variegated brown and black patterning on the shell scutes",
      "where": "over the whole body fur and shell surface"
    }
  ],
  "attached_objects": [],
  "animals": ["goat", "tortoise"],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
